/** Normalize a county name to the table's key format. */
function normalizeCounty(countyName) {
  if (!countyName) return '';
  let c = String(countyName).replace(/\s+County$/i, '').trim();
  // Common variants returned by geocoders and LLM fallbacks.
  const aliases = {
    'saint johns': 'St. Johns', 'st johns': 'St. Johns', 'st. johns': 'St. Johns',
    'saint lucie': 'St. Lucie', 'st lucie': 'St. Lucie', 'st. lucie': 'St. Lucie',
    'miami dade': 'Miami-Dade', 'miami-dade': 'Miami-Dade', 'miamidade': 'Miami-Dade', 'dade': 'Miami-Dade',
    'desoto': 'DeSoto', 'de soto': 'DeSoto',
    'indian river': 'Indian River', 'palm beach': 'Palm Beach', 'santa rosa': 'Santa Rosa',
  };
  const key = c.toLowerCase();
  if (aliases[key]) return aliases[key];
  // Title-case fallback so "ORANGE" and "orange" both resolve.
  // Title-case each ALPHA RUN, not each whitespace-delimited token. `\w\S*`
  // swallowed the hyphen, so "Miami-Dade" normalized to "Miami-dade" — which
  // matched no key in either table, so getFlVabAddress returned null and Florida's
  // LARGEST county was hard-blocked at checkout as "not verified".
  return c.replace(/[A-Za-z]+/g, (t) => t.charAt(0).toUpperCase() + t.slice(1).toLowerCase());
}

/**
 * Get the VAB Clerk mailing address for a Florida county.
 * Returns null if the county is unknown OR unconfirmed — callers MUST treat
 * null as "cannot file" and must never substitute another address.
 */
export function getFlVabAddress(countyName) {
  const entry = FL_VAB_ADDRESSES[normalizeCounty(countyName)];
  if (!entry) return null;
  if (entry.confidence !== 'confirmed') return null;
  return entry;
}

/**
 * ============================================================================
 * LOB CAPS address_line1 + address_line2 AT 50 CHARACTERS, COMBINED.
 * ============================================================================
 * 25 Aug 2026, 10:59Z, order db86d957 — the first paying customer:
 *
 *   The sum (51) of to.address_line1 (601 E KENNEDY BLVD FL 12) and
 *   to.address_line2 (ATTN VALUE ADJUSTMENT BOARD) cannot surpass 50 characters
 *
 * One character over. The card had already been charged, fulfilment threw, the
 * order went to needs_review, and the portal correctly told her we had hit a
 * problem. Money taken, petition not mailed, thirteen days to a
 * receipt-not-postmark deadline.
 *
 * TWO THINGS MADE THIS WORSE THAN A BAD RECORD.
 *
 * First, LOB NORMALISES BEFORE IT MEASURES. We store "601 East Kennedy Blvd,
 * Floor 12" and "Attn: Value Adjustment Board" — 58 characters raw. Lob upcases,
 * strips punctuation and applies USPS abbreviations (East->E, Boulevard->BLVD,
 * Floor->FL), giving 51. So the number that matters is not the one visible in
 * this file, and eyeballing these strings does not tell you whether an order
 * will mail.
 *
 * Second, IT IS NOT ONE COUNTY. Measured across all 61 confirmed entries on
 * 25 Aug, 23 EXCEED THE CAP — Pinellas (85), Leon (73), Pasco (69), Seminole,
 * Columbia, Wakulla, Escambia, Sumter, Hamilton, Duval, Glades, Bay, Collier,
 * Hardee, Hernando, Suwannee, Calhoun, Taylor, Palm Beach, Volusia, Clay,
 * Flagler, Hillsborough. Every order in any of them would have failed the same
 * way, after payment. Hillsborough was simply the first county anyone bought in.
 *
 * WHAT THIS DOES. Produces the two recipient lines Lob will accept, shedding the
 * least load-bearing text first and stopping as soon as it fits:
 *
 *   1. As stored.
 *   2. Drop the "Attn:" prefix — the cheque's payee NAME already carries the
 *      office, so the word itself is overhead.
 *   3. Abbreviate "Value Adjustment Board" to "VAB" — understood by the clerk's
 *      office that receives these, which is the only reader that matters.
 *   4. Drop line 2 entirely. USPS routes on line 1 and the payee name; the
 *      attention line is routing help inside the building, not addressing.
 *
 * IT NEVER TRUNCATES. A cut string can name a different place — "601 E KENNEDY
 * BLVD FL 1" is a real floor and the wrong one — and this address decides where
 * a sworn petition and a cheque physically land. Dropping a whole component is
 * recoverable; a silently wrong one is not.
 *
 * scripts/verify-fl-dispatch.mjs asserts EVERY confirmed county fits after this,
 * so a new address that would blow the cap fails the build instead of failing a
 * customer's order after their card is charged.
 */
export const LOB_ADDRESS_LINE_BUDGET = 50;

/**
 * THE LADDER AIMS BELOW THE CAP, ON PURPOSE.
 *
 * lobNormalizeLine is an INFERENCE of Lob's normalisation, and it is validated
 * against exactly one real sample — the Hillsborough failure, where it
 * reproduces Lob's own reported strings and its 51 character for character.
 * That is good evidence and it is one data point.
 *
 * Aiming at exactly 50 left Collier, Pasco and Pinellas sitting on 50 with zero
 * headroom, so a single token I have guessed wrong — Lob keeping a comma, or
 * expanding "c/o", or an abbreviation not in the table below — reproduces this
 * incident in a different county, after a card is charged.
 *
 * Three characters of margin costs a slightly shorter attention line on a
 * handful of envelopes. Not having it costs an order. Assertions still measure
 * against the true cap of 50; only the shedding decision uses this.
 */
export const LOB_LINE_SAFETY_MARGIN = 3;
export const LOB_LINE_TARGET = LOB_ADDRESS_LINE_BUDGET - LOB_LINE_SAFETY_MARGIN;

const LOB_ABBR = {
  EAST: 'E', WEST: 'W', NORTH: 'N', SOUTH: 'S', NORTHEAST: 'NE', NORTHWEST: 'NW',
  SOUTHEAST: 'SE', SOUTHWEST: 'SW', BOULEVARD: 'BLVD', STREET: 'ST', AVENUE: 'AVE',
  ROAD: 'RD', DRIVE: 'DR', FLOOR: 'FL', SUITE: 'STE', ROOM: 'RM', BUILDING: 'BLDG',
  COURT: 'CT', PLACE: 'PL', LANE: 'LN', HIGHWAY: 'HWY', PARKWAY: 'PKWY',
  TERRACE: 'TER', CIRCLE: 'CIR', ATTENTION: 'ATTN',
};

/**
 * Approximate Lob's own normalisation closely enough to PREDICT its cap.
 *
 * Deliberately conservative: it decides whether to shed a component, and
 * over-estimating a length costs a dropped "Attn:" while under-estimating costs
 * a failed mailing after payment. The lines we SEND are the un-normalised ones —
 * Lob does its own normalisation; this only measures.
 */
export function lobNormalizeLine(s) {
  return String(s || '')
    .toUpperCase()
    .replace(/[.,#:]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .map((w) => LOB_ABBR[w] || w)
    .join(' ');
}

export function lobLineLength(line1, line2) {
  return lobNormalizeLine(line1).length + lobNormalizeLine(line2).length;
}

/**
 * The recipient lines to hand Lob, guaranteed to fit its combined cap.
 *
 * Returns { line1, line2, shed } — `shed` names what was given up, so
 * send-letter can log it and an operator can see why an envelope reads
 * differently from this file. Returns null only if line 1 alone is over, which
 * the build forbids.
 */
export function flVabMailingLines(countyName) {
  const entry = getFlVabAddress(countyName);
  if (!entry) return null;

  const line1 = entry.street;
  const attn = entry.attn || '';
  const noPrefix = attn.replace(/^\s*attn:?\s*/i, '');
  const vab = noPrefix.replace(/value adjustment board/gi, 'VAB');
  /**
   * The county's own name, dropped LAST among the shortenings and only when
   * "VAB" alone was not enough. It is the most redundant token on the envelope —
   * the city, state and ZIP beneath it already say which county this is — but it
   * is dropped after the abbreviation because "Palm Beach County VAB" is more
   * useful to a mailroom than a bare "VAB" when both would fit.
   *
   * This rung exists for Pinellas, whose attention line is 67 characters
   * ("Pinellas County Value Adjustment Board c/o Board Records Department").
   * Without it Pinellas was the one county that lost its line 2 outright — and
   * "c/o Board Records Department" is exactly the part that gets a petition to
   * the right desk. With it, Pinellas lands on 50 and keeps the routing.
   */
  const noCounty = vab.replace(
    new RegExp(`^\\s*${normalizeCounty(countyName).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s+county\\s+`, 'i'),
    ''
  );

  /**
   * Ordinary office words, abbreviated the way a mailroom already writes them.
   * This rung exists so Pinellas and Pasco keep their "c/o <desk>" routing
   * instead of falling through to a bare line — that clause is the difference
   * between a petition reaching the Board Records desk and reaching a mailroom.
   */
  const shortWords = (s) => s
    .replace(/\bDepartment\b/gi, 'Dept')
    .replace(/\bDivision\b/gi, 'Div')
    .replace(/\bAdministration\b/gi, 'Admin')
    .replace(/\bCircuit Court\b/gi, 'Circuit Ct');

  const candidates = [
    { line2: attn, shed: null },
    { line2: noPrefix, shed: 'the "Attn:" prefix' },
    { line2: vab, shed: '"Attn:" and "Value Adjustment Board" shortened to "VAB"' },
    { line2: shortWords(vab), shed: '"Attn:", "VAB", and office words abbreviated' },
    { line2: shortWords(noCounty), shed: '"Attn:", the county name, "VAB", and office words abbreviated' },
    { line2: '', shed: 'the attention line entirely — line 1 and the payee name carry it' },
  ];

  for (const c of candidates) {
    if (lobLineLength(line1, c.line2) <= LOB_LINE_TARGET) {
      return { line1, line2: c.line2 || undefined, shed: c.shed };
    }
  }
  return null;
}

/** Raw lookup including unconfirmed entries — for admin/ops tooling only. */
export function getFlVabAddressRaw(countyName) {
  return FL_VAB_ADDRESSES[normalizeCounty(countyName)] || null;
}

/** True only if we can safely mail a petition for this county today. */
export function isFlCountySupported(countyName) {
  return getFlVabAddress(countyName) !== null;
}

/** True if this county requires physical receipt (postmark not sufficient). */
export function flCountyRequiresReceipt(countyName) {
  return FL_POSTMARK_NOT_ACCEPTED.includes(normalizeCounty(countyName));
}

/** Counties currently blocked pending phone verification. */
/**
 * All 67 Florida county names, sorted. Used to populate the county picker in the
 * apply funnel so a customer can correct or supply their county when the Census
 * geocoder cannot place the address — a DROPDOWN, never free text, because a
 * typo here mails the petition and the fee cheque to the wrong government office.
 */
export const FL_COUNTY_NAMES = Object.keys(FL_VAB_ADDRESSES).sort((a, b) => a.localeCompare(b));

export function getUnconfirmedFlCounties() {
  return Object.entries(FL_VAB_ADDRESSES)
    .filter(([, v]) => v.confidence !== 'confirmed')
    .map(([k]) => k);
}

export default FL_VAB_ADDRESSES;
